    private static readonly Dictionary<string, Geometry> _cache = new();

    /// Все виды, у которых есть значок, — для проверки.
    public static IEnumerable<string> Kinds => Paths.Keys;

    /// Фигура значка по виду тега или иконки; вида нет — null (иконку не рисуем).
    public static Geometry? Of(string kind)
    {
        if (_cache.TryGetValue(kind, out var g)) return g;
        if (!Paths.TryGetValue(kind, out var data)) return null;
        g = Geometry.Parse(data);
        g.Freeze();
        return _cache[kind] = g;
    }
